local RawhideTanner = {}
local PRODUCTS = {
    rawhide = { name = "Surovo usnje", hideCost = 2, limeCost = 1, waterCost = 1, time = 2, cost = 18, quality = 30, description = "Surovo usnje iz surovih kož." },
    bark_tanned_leather = { name = "Skorjno strojeno usnje", hideCost = 3, barkCost = 1, waterCost = 1, time = 4, cost = 50, quality = 50, prestige = 1, description = "Usnje strojeno z lubjem." },
    alum_tawed_leather = { name = "Alun strojeno usnje", hideCost = 3, alumCost = 1, saltCost = 1, time = 5, cost = 120, quality = 65, prestige = 3, happiness = 1, description = "Usnje strojeno z alunom za fine izdelke." },
    oil_tanned_leather = { name = "Oljno strojeno usnje", hideCost = 4, oilCost = 1, barkCost = 1, time = 7, cost = 280, quality = 80, prestige = 6, happiness = 2, description = "Usnje z oljno obdelavo za vodoodpornost." },
    silver_treated_leather = { name = "Srebrno obdelano usnje", hideCost = 5, silverCost = 1, alumCost = 1, oilCost = 1, time = 10, cost = 600, quality = 92, prestige = 12, happiness = 3, description = "Usnje s srebrno obdelavo za plemiče." },
    royal_grand_leather = { name = "Kraljevski veliki usnje", hideCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, barkCost = 2, alumCost = 2, oilCost = 2, time = 15, cost = 1600, quality = 100, prestige = 35, happiness = 8, description = "Veliko kraljevsko usnje z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Strojalna delavnica", cost = { gold = 280, wood = 130, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    tanning_yard = { name = "Strojevalnica", cost = { gold = 950, wood = 250, stone = 400, hide = 10 }, upkeep = 23, qualityBonus = 18 },
    bark_mill = { name = "Mlin lubja", cost = { gold = 2300, wood = 350, stone = 600, silver = 30, bark = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_tanner_atelier = { name = "Kraljevski atelje usnja", cost = { gold = 9500, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 40 },
}
RawhideTanner.hideStock = 22; RawhideTanner.limeStock = 12; RawhideTanner.waterStock = 18; RawhideTanner.barkStock = 14; RawhideTanner.alumStock = 14; RawhideTanner.saltStock = 14; RawhideTanner.oilStock = 12; RawhideTanner.silverStock = 8; RawhideTanner.goldStock = 6; RawhideTanner.jewelStock = 6
RawhideTanner.productStock = {}; RawhideTanner.buildings = {}; RawhideTanner.maker = nil; RawhideTanner.activeMaking = {}; RawhideTanner.totalProducts = 0; RawhideTanner.dayTimer = 0
function RawhideTanner.init() RawhideTanner.hideStock=22; RawhideTanner.limeStock=12; RawhideTanner.waterStock=18; RawhideTanner.barkStock=14; RawhideTanner.alumStock=14; RawhideTanner.saltStock=14; RawhideTanner.oilStock=12; RawhideTanner.silverStock=8; RawhideTanner.goldStock=6; RawhideTanner.jewelStock=6; RawhideTanner.productStock={}; RawhideTanner.buildings={}; RawhideTanner.maker=nil; RawhideTanner.activeMaking={}; RawhideTanner.totalProducts=0; RawhideTanner.dayTimer=0; print("[RawhideTanner] Royal Rawhide Tanner System initialized (6 products, 4 buildings)") end
function RawhideTanner.hireMaker(n,s) s=s or math.random(50,90); local c=510+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RawhideTanner.maker={name=n or ("Strojar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Strojar najet: %s (spretnost: %d)",RawhideTanner.maker.name,s),"success") end; return true end
function RawhideTanner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RawhideTanner.build(id) local ok,e=RawhideTanner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RawhideTanner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RawhideTanner.getQualityBonus() local b=0; for _,bd in ipairs(RawhideTanner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RawhideTanner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.hideCost and RawhideTanner.hideStock<(d.hideCost or 0) then return false,"Premalo kož" end; if d.limeCost and RawhideTanner.limeStock<(d.limeCost or 0) then return false,"Premalo apna" end; if d.waterCost and RawhideTanner.waterStock<(d.waterCost or 0) then return false,"Premalo vode" end; if d.barkCost and RawhideTanner.barkStock<(d.barkCost or 0) then return false,"Premalo lubja" end; if d.alumCost and RawhideTanner.alumStock<(d.alumCost or 0) then return false,"Premalo aluna" end; if d.saltCost and RawhideTanner.saltStock<(d.saltCost or 0) then return false,"Premalo soli" end; if d.oilCost and RawhideTanner.oilStock<(d.oilCost or 0) then return false,"Premalo olja" end; if d.silverCost and RawhideTanner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RawhideTanner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RawhideTanner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #RawhideTanner.buildings==0 then return false,"Potrebna delavnica" end; if not RawhideTanner.maker then return false,"Potreben strojar" end; return true end
function RawhideTanner.make(pt,qty) qty=qty or 5; local ok,e=RawhideTanner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.hideCost then RawhideTanner.hideStock=RawhideTanner.hideStock-d.hideCost*qty end; if d.limeCost then RawhideTanner.limeStock=RawhideTanner.limeStock-d.limeCost*qty end; if d.waterCost then RawhideTanner.waterStock=RawhideTanner.waterStock-d.waterCost*qty end; if d.barkCost then RawhideTanner.barkStock=RawhideTanner.barkStock-d.barkCost*qty end; if d.alumCost then RawhideTanner.alumStock=RawhideTanner.alumStock-d.alumCost*qty end; if d.saltCost then RawhideTanner.saltStock=RawhideTanner.saltStock-d.saltCost*qty end; if d.oilCost then RawhideTanner.oilStock=RawhideTanner.oilStock-d.oilCost*qty end; if d.silverCost then RawhideTanner.silverStock=RawhideTanner.silverStock-d.silverCost*qty end; if d.goldCost then RawhideTanner.goldStock=RawhideTanner.goldStock-d.goldCost*qty end; if d.jewelCost then RawhideTanner.jewelStock=RawhideTanner.jewelStock-d.jewelCost*qty end; local t=d.time; if RawhideTanner.maker then t=math.max(1,t-math.floor(RawhideTanner.maker.skill/12)) end; table.insert(RawhideTanner.activeMaking,{id="rawhide_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RawhideTanner.completeMaking(m) local q=1.0+(RawhideTanner.getQualityBonus()/100); if RawhideTanner.maker then q=q+(RawhideTanner.maker.skill/180) end; q=math.min(2.0,q); RawhideTanner.productStock[m.productType]=(RawhideTanner.productStock[m.productType] or 0)+m.quantity; RawhideTanner.totalProducts=RawhideTanner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RawhideTanner.maker then RawhideTanner.maker.itemsMade=RawhideTanner.maker.itemsMade+m.quantity; if math.random()<0.20 then RawhideTanner.maker.skill=math.min(100,RawhideTanner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Usnje izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"rawhide.completed",{productName=m.productName,quality=m.quality}) end end
function RawhideTanner.update(dt) if not _G.state then return end; RawhideTanner.dayTimer=RawhideTanner.dayTimer+dt; if RawhideTanner.dayTimer>=30 then RawhideTanner.dayTimer=0; for i=#RawhideTanner.activeMaking,1,-1 do local m=RawhideTanner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RawhideTanner.completeMaking(m); table.remove(RawhideTanner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RawhideTanner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RawhideTanner.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RawhideTanner.getStats() return {hideStock=RawhideTanner.hideStock,limeStock=RawhideTanner.limeStock,waterStock=RawhideTanner.waterStock,barkStock=RawhideTanner.barkStock,alumStock=RawhideTanner.alumStock,saltStock=RawhideTanner.saltStock,oilStock=RawhideTanner.oilStock,silverStock=RawhideTanner.silverStock,goldStock=RawhideTanner.goldStock,jewelStock=RawhideTanner.jewelStock,productStock=RawhideTanner.productStock,numBuildings=#RawhideTanner.buildings,hasMaker=RawhideTanner.maker~=nil,makerName=RawhideTanner.maker and RawhideTanner.maker.name or "—",makerSkill=RawhideTanner.maker and RawhideTanner.maker.skill or 0,activeMaking=#RawhideTanner.activeMaking,totalProducts=RawhideTanner.totalProducts} end
return RawhideTanner
